7	)
8	
9	// 本文件回归保障预留失败历史（RequestHistory）的拒绝事实归属：每次历史查询
10	// 返回的记录列表、资格依据快照（含已经有内容的拒绝原因列表）与库存依据快照
11	// 都是属于调用方的副本。调用方拿到失败记录后可以为了展示任意整理自己那份
12	// 内容——改写拒绝原因、合格标记、处理结果、提交数量、库存依据，删除或补入
13	// 列表记录——但这些编辑只能影响这一份数据，不能覆盖或丢失仓库保存的拒绝
14	// 事实：另一份此前取回的结果、重新查询的历史、按请求的资格与承诺查询、按
15	// 备件的库存账目都继续反映真实处理结果，失败不能变成成功，被拒绝的数量不
16	// 能进入占用，仓库保存的提交次数也不随调用方列表的增删而增减。这些测试只
17	// 沿用登记、预留与查询等既有公开行为与现有的预留错误类别、依据快照和按请求
18	// 查询约定，不改变任何资格规则、库存规则和错误行为。
19	
20	// 本文件专用编号，避免与其他测试文件混用。
21	const (
22		hrProductID = "p-hrej"
23		hrPartID    = "part-hrej"
24		hrOKReq     = "r-ok"
25		hrBadReq    = "r-bad"
26		hrEmptyReq  = "r-empty"
27		hrOKCommit  = "c-ok"
28		hrBadCommit = "c-bad"
29	)
30	
31	// hrClock 汇集主例的全部时刻。
32	type hrClock struct {
33		deadline  time.Time // 保修截止时刻：购买时刻起第三十天
34		okAt      time.Time // 保修期内第一次预留的当前时刻
35		okExpiry  time.Time // 第一次预留的承诺到期时刻，晚于随后查询与第二次预留的时刻
36		badAt     time.Time // 产品已过保后第二次预留的当前时刻
37		badExpiry time.Time // 第二次预留给定的到期时刻，本身有效（晚于 badAt）
38	}
39	
40	// hrScenario 构造用户给出的主例：产品保修三十天，BROKEN_SEAL 在除外故障
41	// 代码中，备件初始库存十件。先在保修期内为未命中除外代码的 r-ok（故障
42	// NOISE）预留四件，承诺到期晚于随后的查询与第二次预留时刻；再在产品已过
43	// 保后，为命中 BROKEN_SEAL 的 r-bad 预留两件，到期参数本身有效，该次预留
44	// 返回 ErrIneligible。另有一个已登记但没有任何预留记录的 r-empty。
45	func hrScenario(t *testing.T) (*Store, hrClock) {
46		t.Helper()
47		clk := hrClock{
48			deadline:  t0.Add(30 * day),
49			okAt:      t0.Add(10 * day),
50			okExpiry:  t0.Add(45 * day),
51			badAt:     t0.Add(31 * day),
52			badExpiry: t0.Add(40 * day),
53		}
54	
55		s := NewStore()
56		if err := s.RegisterProduct(hrProductID, t0, 30, []string{"BROKEN_SEAL"}); err != nil {
57			t.Fatalf("register product: %v", err)
58		}
59		if err := s.RegisterPart(hrPartID, 10); err != nil {
60			t.Fatalf("register part: %v", err)
61		}
62		if err := s.SubmitRequest(hrOKReq, hrProductID, "NOISE"); err != nil {
63			t.Fatalf("submit ok request: %v", err)
64		}
65		if err := s.SubmitRequest(hrBadReq, hrProductID, "BROKEN_SEAL"); err != nil {
66			t.Fatalf("submit bad request: %v", err)
67		}
68		if err := s.SubmitRequest(hrEmptyReq, hrProductID, "NOISE"); err != nil {
69			t.Fatalf("submit empty request: %v", err)
70		}
71	
72		// 保修期内为未命中除外代码的请求预留四件，成功占用。
73		if _, err := s.Reserve(hrOKCommit, hrOKReq, hrPartID, 4, clk.okExpiry, clk.okAt); err != nil {
74			t.Fatalf("reserve within warranty: %v", err)
75		}
76		// 产品已过保且命中除外代码：返回 ErrIneligible，到期参数本身有效。
77		if _, err := s.Reserve(hrBadCommit, hrBadReq, hrPartID, 2, clk.badExpiry, clk.badAt); !errors.Is(err, ErrIneligible) {
78			t.Fatalf("reserve expired+excluded: got %v, want ErrIneligible", err)
79		}
80		return s, clk
81	}
82	
83	// assertRejectionRecord 断言一条历史记录完整保留主例中的拒绝事实：归属
84	// r-bad 的次序号一、提交内容为 c-bad/part-hrej/两件与给定时刻，处理结果
85	// 是类别为 ineligible 的失败；资格依据仍是登记的购买时刻、保修三十天与
86	// 保修截止时刻，不合格且命中除外，拒绝原因恰好为过保与故障除外两项且
87	// 次序不变；库存依据为处理前实物十件、有效占用四件、可承诺六件。
88	func assertRejectionRecord(t *testing.T, rec HistoryRecord, clk hrClock) {
89		t.Helper()
90		if rec.Seq != 1 {
91			t.Fatalf("seq = %d, want 1", rec.Seq)
92		}
93		if rec.Success {
94			t.Fatalf("failure record became success: %+v", rec)
95		}
96		if rec.Error != HistoryErrorIneligible {
97			t.Fatalf("error category = %q, want %q", rec.Error, HistoryErrorIneligible)
98		}
99		if rec.CommitID != hrBadCommit || rec.PartID != hrPartID || rec.Quantity != 2 {
100			t.Fatalf("submission content = %q/%q/%d, want %q/%q/2",
101				rec.CommitID, rec.PartID, rec.Quantity, hrBadCommit, hrPartID)
102		}
103		if !rec.Expiry.Equal(clk.badExpiry) || !rec.Now.Equal(clk.badAt) {
104			t.Fatalf("times = expiry %v now %v, want %v / %v", rec.Expiry, rec.Now, clk.badExpiry, clk.badAt)
105		}
106	
107		e := rec.Eligibility
108		if e == nil {
109			t.Fatal("expected eligibility snapshot on rejected record")
110		}
111		if e.RequestID != hrBadReq || e.ProductID != hrProductID || e.FaultCode != "BROKEN_SEAL" {
112			t.Fatalf("eligibility identity = %q/%q/%q, want %q/%q/BROKEN_SEAL",
113				e.RequestID, e.ProductID, e.FaultCode, hrBadReq, hrProductID)
114		}
115		if e.Eligible {
116			t.Fatalf("eligible = true, want false: %+v", e)
117		}
118		if !e.Excluded {
119			t.Fatalf("excluded = false, want true: %+v", e)
120		}
121		if len(e.Reasons) != 2 || e.Reasons[0] != ReasonWarrantyExpired || e.Reasons[1] != ReasonFaultExcluded {
122			t.Fatalf("reasons = %v, want exactly [warranty_expired fault_code_excluded]", e.Reasons)
123		}
124		if !e.PurchaseTime.Equal(t0) || e.WarrantyDays != 30 || !e.WarrantyExpiry.Equal(clk.deadline) {
125			t.Fatalf("registered eligibility basis altered: purchase=%v days=%d expiry=%v",
126				e.PurchaseTime, e.WarrantyDays, e.WarrantyExpiry)
127		}
128	
129		b := rec.StockBasis
130		if b == nil {
131			t.Fatal("expected stock basis snapshot on rejected record")
132		}
133		if b.PhysicalRemaining != 10 || b.ActiveOccupied != 4 || b.Committable != 6 {
134			t.Fatalf("stock basis = phys %d / occupied %d / committable %d, want 10/4/6",
135				b.PhysicalRemaining, b.ActiveOccupied, b.Committable)
136		}
137	}
138	
139	// assertRejectionState 断言仓库真实状态保留拒绝事实：被拒绝的两件没有成为
140	// 承诺，也没有进入占用——备件账目始终是实物十件、有效占用四件、可承诺六件，
141	// 明细只有 r-ok 那笔四件的有效承诺；直接查询 r-bad 的资格仍得到过保与故障
142	// 除外两项原因，按请求查看没有任何关联承诺。
143	func assertRejectionState(t *testing.T, s *Store, clk hrClock) {
144		t.Helper()
145		if _, err := s.Commitment(hrBadCommit); !errors.Is(err, ErrNotFound) {
146			t.Fatalf("rejected commitment %q exists: err=%v", hrBadCommit, err)
147		}
148	
149		st, err := s.PartStatus(hrPartID, clk.badAt)
150		if err != nil {
151			t.Fatalf("part status: %v", err)
152		}
153		if st.PhysicalRemaining != 10 || st.ActiveOccupied != 4 || st.Committable != 6 {
154			t.Fatalf("stock after rejection = phys %d / occupied %d / committable %d, want 10/4/6",
155				st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
156		}
157		if len(st.Details) != 1 {
158			t.Fatalf("part details = %+v, want only the four-unit commitment", st.Details)
159		}
160		d := st.Details[0]
161		if d.CommitmentID != hrOKCommit || d.RequestID != hrOKReq || d.OriginalQuantity != 4 ||
162			d.UsedQuantity != 0 || d.RemainingQuantity != 4 || d.Status != CommitmentActive ||
163			!d.Expiry.Equal(clk.okExpiry) {
164			t.Fatalf("only commitment detail altered: %+v", d)
165		}
166	
167		e, err := s.Evaluate(hrBadReq, clk.badAt)
168		if err != nil {
169			t.Fatalf("evaluate rejected request: %v", err)
170		}
171		if e.Eligible || !e.Excluded || len(e.Reasons) != 2 ||
172			e.Reasons[0] != ReasonWarrantyExpired || e.Reasons[1] != ReasonFaultExcluded {
173			t.Fatalf("direct eligibility = %+v, want ineligible with both rejection reasons", e)
174		}
175	
176		view, err := s.RequestView(hrBadReq, clk.badAt)
177		if err != nil {
178			t.Fatalf("request view: %v", err)
179		}
180		if view.Eligibility == nil || view.Eligibility.Eligible ||
181			len(view.Eligibility.Reasons) != 2 ||
182			view.Eligibility.Reasons[0] != ReasonWarrantyExpired ||
183			view.Eligibility.Reasons[1] != ReasonFaultExcluded {
184			t.Fatalf("view eligibility = %+v, want both rejection reasons", view.Eligibility)
185		}
186		if len(view.Commitments) != 0 {
187			t.Fatalf("rejected request gained commitments: %+v", view.Commitments)
188		}
189	}
190	
191	// TestRejectedHistoryFactSurvivesCallerEdits 主例：过保且命中 BROKEN_SEAL
192	// 的两件预留返回 ErrIneligible。对失败记录分别取回两份历史，调用方把其中
193	// 一份已有的拒绝原因改成其他原因，并改动合格标记、处理结果、提交数量和
194	// 库存依据，再在自己的列表里补入和删除记录；另一份此前取回的结果以及
195	// 重新查询的历史都必须保留原事实——请求归属、提交内容、次序号和两项拒绝
196	// 原因不被覆盖或丢失，失败不变成成功，提交次数不增不减，资格与备件查询
197	// 也不能因为编辑返回值而放行或发放备件。
198	func TestRejectedHistoryFactSurvivesCallerEdits(t *testing.T) {
199		s, clk := hrScenario(t)
200	
201		// 拒绝事实在任何编辑之前先核对一次。
202		assertRejectionState(t, s, clk)
203	
204		first, err := s.RequestHistory(hrBadReq)
205		if err != nil {
206			t.Fatalf("first history: %v", err)
207		}
208		second, err := s.RequestHistory(hrBadReq)
209		if err != nil {
210			t.Fatalf("second history: %v", err)
211		}
212		if len(first) != 1 || len(second) != 1 {
213			t.Fatalf("history lengths = %d / %d, want 1 / 1", len(first), len(second))
214		}
215		assertRejectionRecord(t, first[0], clk)
216		assertRejectionRecord(t, second[0], clk)
217	
218		// 调用方为了展示任意整理第一份结果：
219		rec := &first[0]
220		rec.Seq = 99
221		rec.CommitID = "c-fake"
222		rec.PartID = "part-fake"
223		rec.Quantity = 99
224		rec.Expiry = t0
225		rec.Now = t0
226		// 处理结果：失败改写成成功。
227		rec.Success = true
228		rec.Error = ""
229		// 资格依据：就地改写已有拒绝原因底层数组，再翻合格标记、除外标记和归属，
230		// 最后把拒绝原因整体替换成另一项原因。
231		rec.Eligibility.Reasons[0] = ReasonPurchaseInFuture
232		rec.Eligibility.Eligible = true
233		rec.Eligibility.Excluded = false
234		rec.Eligibility.RequestID = "r-fake"
235		rec.Eligibility.ProductID = "p-fake"
236		rec.Eligibility.FaultCode = "NOISE"
237		rec.Eligibility.PurchaseTime = t0.Add(99 * day)
238		rec.Eligibility.WarrantyDays = 365
239		rec.Eligibility.WarrantyExpiry = t0.Add(365 * day)
240		rec.Eligibility.Reasons = []RejectionReason{ReasonPurchaseInFuture}
241		// 库存依据：先就地改字段，再整体换成另一份依据。
242		rec.StockBasis.PhysicalRemaining = 100
243		rec.StockBasis.ActiveOccupied = 90
244		rec.StockBasis.Committable = 10
245		rec.StockBasis = &StockBasis{PhysicalRemaining: 1, ActiveOccupied: 1, Committable: 0}
246		// 在调用方自己的列表中补入一条伪造的成功记录。
247		first = append(first, HistoryRecord{Seq: 2, CommitID: "c-added", Success: true})
248	
249		// 另一份此前取回的结果保留全部原事实，包括拒绝原因底层数组。
250		if len(second) != 1 {
251			t.Fatalf("earlier copy length = %d, want 1", len(second))
252		}
253		assertRejectionRecord(t, second[0], clk)
254	
255		// 重新查询：补入不增加仓库保存的提交次数，原记录仍归属 r-bad 且序号为一。
256		again, err := s.RequestHistory(hrBadReq)
257		if err != nil {
258			t.Fatalf("re-query after append: %v", err)
259		}
260		if len(again) != 1 {
261			t.Fatalf("re-query length = %d, want 1 (caller append must not be saved)", len(again))
262		}
263		assertRejectionRecord(t, again[0], clk)
264	
265		// 调用方从自己那份列表删除记录（连同此前补入的伪造记录一起清空）。
266		first = first[:0]
267	
268		// 删除不减少仓库保存的提交次数。
269		again2, err := s.RequestHistory(hrBadReq)
270		if err != nil {
271			t.Fatalf("re-query after delete: %v", err)
272		}
273		if len(again2) != 1 {
274			t.Fatalf("re-query length = %d, want 1 (caller delete must not remove saved record)", len(again2))
275		}
276		assertRejectionRecord(t, again2[0], clk)
277	
278		// 编辑返回值不能放行资格、不能发放备件，也不能造出成功承诺。
279		assertRejectionState(t, s, clk)
280	
281		// 其他请求的历史不受影响：r-ok 仍只有第一次预留的成功记录，其库存
282		// 依据是那次提交处理前的实物十件、占用零、可承诺十件。
283		okHistory, err := s.RequestHistory(hrOKReq)
284		if err != nil {
285			t.Fatalf("ok request history: %v", err)
286		}
287		if len(okHistory) != 1 {
288			t.Fatalf("ok history length = %d, want 1", len(okHistory))
289		}
290		okRec := okHistory[0]
291		if okRec.Seq != 1 || !okRec.Success || okRec.Error != "" ||
292			okRec.CommitID != hrOKCommit || okRec.PartID != hrPartID || okRec.Quantity != 4 ||
293			!okRec.Expiry.Equal(clk.okExpiry) || !okRec.Now.Equal(clk.okAt) {
294			t.Fatalf("ok success record altered: %+v", okRec)
295		}
296		if okRec.Eligibility == nil || !okRec.Eligibility.Eligible || okRec.Eligibility.Excluded ||
297			len(okRec.Eligibility.Reasons) != 0 ||
298			!okRec.Eligibility.PurchaseTime.Equal(t0) || okRec.Eligibility.WarrantyDays != 30 ||
299			!okRec.Eligibility.WarrantyExpiry.Equal(clk.deadline) {
300			t.Fatalf("ok eligibility snapshot altered: %+v", okRec.Eligibility)
301		}
302		if okRec.StockBasis == nil || okRec.StockBasis.PhysicalRemaining != 10 ||
303			okRec.StockBasis.ActiveOccupied != 0 || okRec.StockBasis.Committable != 10 {
304			t.Fatalf("ok stock basis altered: %+v", okRec.StockBasis)
305		}
306	}
307	
308	// TestEmptyHistoryStaysEmptyAfterCallerAppends 已登记但没有预留记录的请求：
309	// 取回的历史是空列表；调用方在自己的列表中加入伪造记录后，再次查询仍为
310	// 空列表，仓库中其他请求的成功与失败历史也不受影响。
311	func TestEmptyHistoryStaysEmptyAfterCallerAppends(t *testing.T) {
312		s, clk := hrScenario(t)
313	
314		empty, err := s.RequestHistory(hrEmptyReq)
315		if err != nil {
316			t.Fatalf("empty history: %v", err)
317		}
318		if empty == nil || len(empty) != 0 {
319			t.Fatalf("registered request without reserves: got %v, want empty non-nil list", empty)
320		}
321	
322		// 调用方在自己的空列表中补入伪造的成功与失败记录。
323		empty = append(empty,
324			HistoryRecord{Seq: 1, CommitID: "c-fake-1", PartID: hrPartID, Quantity: 3, Success: true},
325			HistoryRecord{Seq: 2, CommitID: "c-fake-2", PartID: hrPartID, Quantity: 5, Success: false, Error: HistoryErrorIneligible},
326		)
327	
328		// 再次查询仍为空列表（非 nil），伪造记录没有进入仓库，提交次数为零。
329		again, err := s.RequestHistory(hrEmptyReq)
330		if err != nil {
331			t.Fatalf("re-query empty history: %v", err)
332		}
333		if again == nil || len(again) != 0 {
334			t.Fatalf("empty history gained records: %+v", again)
335		}
336	
337		// 其他请求的历史不受影响：r-bad 仍是那一条拒绝事实，r-ok 仍是那一条成功。
338		badHistory, err := s.RequestHistory(hrBadReq)
339		if err != nil {
340			t.Fatalf("bad history: %v", err)
341		}
342		if len(badHistory) != 1 {
343			t.Fatalf("bad history length = %d, want 1", len(badHistory))
344		}
345		assertRejectionRecord(t, badHistory[0], clk)
346	
347		okHistory, err := s.RequestHistory(hrOKReq)
348		if err != nil {
349			t.Fatalf("ok history: %v", err)
350		}
351		if len(okHistory) != 1 || !okHistory[0].Success || okHistory[0].CommitID != hrOKCommit {
352			t.Fatalf("ok history altered: %+v", okHistory)
353		}
354	
355		// 备件账目也不被伪造记录占用：仍是 10/4/6。
356		st, err := s.PartStatus(hrPartID, clk.badAt)
357		if err != nil {
358			t.Fatalf("part status: %v", err)
359		}
360		if st.PhysicalRemaining != 10 || st.ActiveOccupied != 4 || st.Committable != 6 {
361			t.Fatalf("stock after fabricating empty-history records = %d/%d/%d, want 10/4/6",
362				st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
363		}
364	}
