8	
9	// 本文件回归保障同一笔“首次预留”同时撞上保修资格不合格与库存不足时，拒绝
10	// 结果必须归属资格：返回 ErrIneligible 而不是 ErrInsufficientStock，过保与
11	// 除外同时成立时两项拒绝原因都保留。库存紧张不能把过保或命中除外清单的请求
12	// 记录成缺货：被拒编号不产生承诺、不占用数量，原承诺的已用/未用数量与备件
13	// 三项账目（实物剩余/有效占用/可承诺）保持处理前的值；该请求的处理历史新增
14	// 一条 ineligible 失败记录，保存本次提交的数量与时刻，资格依据与按同一时刻
15	// 直接查询（Evaluate、RequestView）的结论一致，库存依据是处理前的真实账目，
16	// 既不是空依据或零库存，也不混入本次申请的数量。
17	//
18	// 主例：备件初始十件；先为合格请求 r-epri-ok 预留八件（c-epri-first），再
19	// 成功使用两件（u-epri-first）。原承诺未到期也未取消，于是实物剩余八件、
20	// 有效占用六件、可承诺两件。随后各用例以“从未预留成功”的新编号，为另一张
21	// 已知请求申请三件（数量为正，到期时刻晚于本次当前时刻）。
22	//
23	// 边界覆盖：当前时刻恰好达到保修截止时刻、可承诺数量恰好为零，都不能让库存
24	// 不足覆盖资格拒绝；作为对照，产品在保且故障未被除外的请求在同样库存不足时
25	// 仍按现有规则返回 ErrInsufficientStock，历史保存合格资格与真实库存依据。
26	// 这些检查全部围绕尚未成功预留的编号，另含已成功编号原样重试结果不变的
27	// 核对，不增加任何新的预留规则。
28	
29	// 本文件专用编号，避免与其他测试文件混用。
30	const (
31		epProductID = "p-epri"
32		epPartID    = "part-epri"
33	
34		// epQualifiedReq 是先占用库存的在保合格请求（故障 NOISE 不在除外清单）。
35		epQualifiedReq = "r-epri-ok"
36		// epFirstCommit 是八件的首次成功承诺；epTailCommit 只在可承诺为零的
37		// 场景追加两件占用。
38		epFirstCommit = "c-epri-first"
39		epTailCommit  = "c-epri-tail"
40		epFirstUse    = "u-epri-first"
41	
42		// 四张各自只提交一次的不合格请求，分别对应仅过保、仅除外、两者同时成立，
43		// 以及当前时刻恰好达到保修截止时刻。
44		epExpiredReq  = "r-epri-exp"
45		epExcludedReq = "r-epri-exc"
46		epBothReq     = "r-epri-both"
47		epBoundaryReq = "r-epri-edge"
48	
49		epExpiredCommit  = "c-epri-exp"
50		epExcludedCommit = "c-epri-exc"
51		epBothCommit     = "c-epri-both"
52		epBoundaryCommit = "c-epri-edge"
53	
54		// 合格对照请求：在保且故障未被除外，库存不足时仍按缺货拒绝。
55		epGoodReq    = "r-epri-good"
56		epGoodCommit = "c-epri-good"
57	
58		// 可承诺为零场景下的不合格请求与合格对照请求。
59		epZeroReq        = "r-epri-zero"
60		epZeroCommit     = "c-epri-zero"
61		epZeroEdgeReq    = "r-epri-zeroedge"
62		epZeroEdgeCommit = "c-epri-zeroedge"
63		epZeroGoodReq    = "r-epri-zerogood"
64		epZeroGoodCommit = "c-epri-zerogood"
65	)
66	
67	// 本文件的全部时刻：保修三十天，截止 t0+30d；八件承诺在 t0+10d 预留并使用，
68	// 承诺到期 t0+90d（晚于本文件所有“当前时刻”，因此拒绝期间它始终有效占用）；
69	// 被拒申请给定的到期时刻 t0+60d，晚于所有拒绝用例的当前时刻。
70	var (
71		epDeadline     = t0.Add(30 * day)
72		epReserveAt    = t0.Add(10 * day)
73		epWithinAt     = t0.Add(20 * day) // 保修期内（仅除外用例与合格对照用）
74		epExpiredAt    = t0.Add(31 * day) // 已过保
75		epCommitExpiry = t0.Add(90 * day)
76		epReqExpiry    = t0.Add(60 * day)
77		epRetryAt      = t0.Add(60 * day) // 已过保但仍早于原承诺到期时刻
78	)
79	
80	// epNewStore 构造主例：登记保修三十天、BROKEN_SEAL 在除外清单中的产品，初始
81	// 十件的备件和合格请求 r-epri-ok；预留八件后成功使用两件。结束时实物八件、
82	// 有效占用六件、可承诺两件，原承诺有效（未取消、未到期）。
83	func epNewStore(t *testing.T) *Store {
84		t.Helper()
85		s := NewStore()
86		if err := s.RegisterProduct(epProductID, t0, 30, []string{"BROKEN_SEAL"}); err != nil {
87			t.Fatalf("register product: %v", err)
88		}
89		if err := s.RegisterPart(epPartID, 10); err != nil {
90			t.Fatalf("register part: %v", err)
91		}
92		if err := s.SubmitRequest(epQualifiedReq, epProductID, "NOISE"); err != nil {
93			t.Fatalf("submit qualified request: %v", err)
94		}
95		if _, err := s.Reserve(epFirstCommit, epQualifiedReq, epPartID, 8, epCommitExpiry, epReserveAt); err != nil {
96			t.Fatalf("reserve eight units: %v", err)
97		}
98		if _, err := s.Use(epFirstUse, epFirstCommit, 2, epReserveAt); err != nil {
99			t.Fatalf("use two units: %v", err)
100		}
101		return s
102	}
103	
104	// epAssertAccount 断言备件三项账目为期望值。
105	func epAssertAccount(t *testing.T, s *Store, now time.Time, physical, occupied, committable int) {
106		t.Helper()
107		st, err := s.PartStatus(epPartID, now)
108		if err != nil {
109			t.Fatalf("part status: %v", err)
110		}
111		if st.PhysicalRemaining != physical || st.ActiveOccupied != occupied || st.Committable != committable {
112			t.Fatalf("stock account = phys %d / occupied %d / committable %d, want %d/%d/%d",
113				st.PhysicalRemaining, st.ActiveOccupied, st.Committable, physical, occupied, committable)
114		}
115	}
116	
117	// epAssertFirstCommitmentUnchanged 断言八件原承诺的数量账目没有被任何拒绝
118	// 改动：原定八件、已用两件、未用六件，未取消、未确认到期，在 now（早于其
119	// 到期时刻）查明细仍为 active。
120	func epAssertFirstCommitmentUnchanged(t *testing.T, s *Store, now time.Time) {
121		t.Helper()
122		c, err := s.Commitment(epFirstCommit)
123		if err != nil {
124			t.Fatalf("load first commitment: %v", err)
125		}
126		if c.Quantity != 8 || c.Used != 2 || c.Unused() != 6 || c.Canceled || c.Expired ||
127			!c.Expiry.Equal(epCommitExpiry) || c.RequestID != epQualifiedReq || c.PartID != epPartID {
128			t.Fatalf("first commitment altered: %+v", c)
129		}
130		st, err := s.PartStatus(epPartID, now)
131		if err != nil {
132			t.Fatalf("part status: %v", err)
133		}
134		var detail *CommitmentDetail
135		for i := range st.Details {
136			if st.Details[i].CommitmentID == epFirstCommit {
137				detail = &st.Details[i]
138			}
139		}
140		if detail == nil {
141			t.Fatalf("first commitment missing from details: %+v", st.Details)
142		}
143		if detail.OriginalQuantity != 8 || detail.UsedQuantity != 2 ||
144			detail.RemainingQuantity != 6 || detail.Status != CommitmentActive {
145			t.Fatalf("first commitment detail altered: %+v", detail)
146		}
147	}
148	
149	// epAssertEligibilityEqual 断言两份资格依据结论完全一致（含拒绝原因列表的
150	// 内容与次序），用于核对历史快照与按同一时刻直接查询的结论一致。
151	func epAssertEligibilityEqual(t *testing.T, got, want *Eligibility, ctx string) {
152		t.Helper()
153		if got == nil || want == nil {
154			t.Fatalf("%s: eligibility must not be nil: got=%v want=%v", ctx, got, want)
155		}
156		if got.RequestID != want.RequestID || got.ProductID != want.ProductID ||
157			got.FaultCode != want.FaultCode || got.Eligible != want.Eligible ||
158			got.Excluded != want.Excluded || got.WarrantyDays != want.WarrantyDays ||
159			!got.PurchaseTime.Equal(want.PurchaseTime) ||
160			!got.WarrantyExpiry.Equal(want.WarrantyExpiry) {
161			t.Fatalf("%s: eligibility basis mismatch:\n got=%+v\nwant=%+v", ctx, got, want)
162		}
163		if len(got.Reasons) != len(want.Reasons) {
164			t.Fatalf("%s: reasons = %v, want %v", ctx, got.Reasons, want.Reasons)
165		}
166		for i := range got.Reasons {
167			if got.Reasons[i] != want.Reasons[i] {
168				t.Fatalf("%s: reasons = %v, want %v", ctx, got.Reasons, want.Reasons)
169			}
170		}
171	}
172	
173	// epAssertIneligibleRecord 核对一条 ineligible 失败记录：归属 reqID、序号
174	// seq、保存本次提交的编号/备件/三件数量与时刻，资格依据与同一时刻的直接
175	// 查询结论一致且拒绝原因恰为 wantReasons，库存依据恰为 wantBasis。
176	func epAssertIneligibleRecord(t *testing.T, s *Store, reqID, commitID string,
177		now time.Time, wantReasons []RejectionReason, wantExcluded bool, wantBasis StockBasis, seq int) {
178		t.Helper()
179	
180		h, err := s.RequestHistory(reqID)
181		if err != nil {
182			t.Fatalf("history %q: %v", reqID, err)
183		}
184		if len(h) != seq {
185			t.Fatalf("history %q length = %d, want %d", reqID, len(h), seq)
186		}
187		rec := h[seq-1]
188		if rec.Seq != seq || rec.Success {
189			t.Fatalf("record seq/success = %d/%v, want %d/false", rec.Seq, rec.Success, seq)
190		}
191		if rec.Error != HistoryErrorIneligible {
192			t.Fatalf("error category = %q, want %q", rec.Error, HistoryErrorIneligible)
193		}
194		if rec.CommitID != commitID || rec.PartID != epPartID || rec.Quantity != 3 {
195			t.Fatalf("submission = %q/%q/%d, want %q/%q/3",
196				rec.CommitID, rec.PartID, rec.Quantity, commitID, epPartID)
197		}
198		if !rec.Expiry.Equal(epReqExpiry) || !rec.Now.Equal(now) {
199			t.Fatalf("submitted times = expiry %v now %v, want %v / %v",
200				rec.Expiry, rec.Now, epReqExpiry, now)
201		}
202	
203		if rec.Eligibility == nil {
204			t.Fatalf("history %q: eligibility basis must not be nil", reqID)
205		}
206		if rec.Eligibility.Eligible {
207			t.Fatalf("history %q: eligible = true, want false", reqID)
208		}
209		if rec.Eligibility.Excluded != wantExcluded {
210			t.Fatalf("history %q: excluded = %v, want %v", reqID, rec.Eligibility.Excluded, wantExcluded)
211		}
212		if len(rec.Eligibility.Reasons) != len(wantReasons) {
213			t.Fatalf("history %q: reasons = %v, want %v", reqID, rec.Eligibility.Reasons, wantReasons)
214		}
215		for i := range wantReasons {
216			if rec.Eligibility.Reasons[i] != wantReasons[i] {
217				t.Fatalf("history %q: reasons = %v, want %v", reqID, rec.Eligibility.Reasons, wantReasons)
218			}
219		}
220		// 资格依据与按同一时刻直接查询的结论一致。
221		direct, err := s.Evaluate(reqID, now)
222		if err != nil {
223			t.Fatalf("direct evaluate %q: %v", reqID, err)
224		}
225		epAssertEligibilityEqual(t, rec.Eligibility, direct, "history vs Evaluate "+reqID)
226		view, err := s.RequestView(reqID, now)
227		if err != nil {
228			t.Fatalf("request view %q: %v", reqID, err)
229		}
230		epAssertEligibilityEqual(t, rec.Eligibility, view.Eligibility, "history vs RequestView "+reqID)
231		if len(view.Commitments) != 0 {
232			t.Fatalf("rejected request %q gained commitments: %+v", reqID, view.Commitments)
233		}
234	
235		if rec.StockBasis == nil {
236			t.Fatalf("history %q: stock basis must not be nil (must not be treated as empty/zero)", reqID)
237		}
238		if *rec.StockBasis != wantBasis {
239			t.Fatalf("history %q: stock basis = %+v, want %+v", reqID, *rec.StockBasis, wantBasis)
240		}
241	}
242	
243	// TestIneligibleBeatsInsufficientStockWhenStockTight 主例回归：可承诺只有
244	// 两件时，申请三件的首次预留只要资格不合格，就必须返回 ErrIneligible 而不是
245	// ErrInsufficientStock。逐例覆盖仅过保、仅命中除外清单、过保与除外同时
246	// 成立、当前时刻恰好达到保修截止时刻；被拒申请不产生承诺、不改变 8/6/2
247	// 账目与原承诺，历史新增 ineligible 记录且依据真实完整。
248	func TestIneligibleBeatsInsufficientStockWhenStockTight(t *testing.T) {
249		s := epNewStore(t)
250	
251		// 主例基线：实物八件、有效占用六件、可承诺两件。
252		epAssertAccount(t, s, epExpiredAt, 8, 6, 2)
253	
254		cases := []struct {
255			name        string
256			reqID       string
257			fault       string
258			commitID    string
259			now         time.Time
260			reasons     []RejectionReason
261			wantExclude bool
262		}{
263			{
264				name:        "expired_only",
265				reqID:       epExpiredReq,
266				fault:       "NOISE",
267				commitID:    epExpiredCommit,
268				now:         epExpiredAt,
269				reasons:     []RejectionReason{ReasonWarrantyExpired},
270				wantExclude: false,
271			},
272			{
273				name:        "excluded_only_within_warranty",
274				reqID:       epExcludedReq,
275				fault:       "BROKEN_SEAL",
276				commitID:    epExcludedCommit,
277				now:         epWithinAt,
278				reasons:     []RejectionReason{ReasonFaultExcluded},
279				wantExclude: true,
280			},
281			{
282				name:        "expired_and_excluded",
283				reqID:       epBothReq,
284				fault:       "BROKEN_SEAL",
285				commitID:    epBothCommit,
286				now:         epExpiredAt,
287				reasons:     []RejectionReason{ReasonWarrantyExpired, ReasonFaultExcluded},
288				wantExclude: true,
289			},
290			{
291				name:        "current_time_exactly_at_warranty_deadline",
292				reqID:       epBoundaryReq,
293				fault:       "NOISE",
294				commitID:    epBoundaryCommit,
295				now:         epDeadline,
296				reasons:     []RejectionReason{ReasonWarrantyExpired},
297				wantExclude: false,
298			},
299		}
300	
301		wantBasis := StockBasis{PhysicalRemaining: 8, ActiveOccupied: 6, Committable: 2}
302		for _, tc := range cases {
303			t.Run(tc.name, func(t *testing.T) {
304				if err := s.SubmitRequest(tc.reqID, epProductID, tc.fault); err != nil {
305					t.Fatalf("submit request: %v", err)
306				}
307	
308				_, err := s.Reserve(tc.commitID, tc.reqID, epPartID, 3, epReqExpiry, tc.now)
309				if !errors.Is(err, ErrIneligible) {
310					t.Fatalf("reserve: got %v, want ErrIneligible", err)
311				}
312				// 关键归属：不能因为可承诺只有两件就把不合格请求报成缺货。
313				if errors.Is(err, ErrInsufficientStock) {
314					t.Fatalf("ineligible reserve wrapped ErrInsufficientStock: %v", err)
315				}
316	
317				// 拒绝不产生承诺，被拒编号仍未占用。
318				if _, err := s.Commitment(tc.commitID); !errors.Is(err, ErrNotFound) {
319					t.Fatalf("commitment %q created by rejection: err=%v", tc.commitID, err)
320				}
321	
322				// 历史新增一条 ineligible 失败记录，资格与库存依据真实完整。
323				epAssertIneligibleRecord(t, s, tc.reqID, tc.commitID, tc.now,
324					tc.reasons, tc.wantExclude, wantBasis, 1)
325	
326				// 原承诺与备件三项账目保持处理前的值：申请的三件没有进入占用。
327				epAssertAccount(t, s, tc.now, 8, 6, 2)
328				epAssertFirstCommitmentUnchanged(t, s, tc.now)
329			})
330		}
331	
332		// 四个用例的拒绝彼此不累积：最终账目仍是 8/6/2，原承诺仍是八件预留、
333		// 两件已用、六件未用的有效承诺。
334		epAssertAccount(t, s, epExpiredAt, 8, 6, 2)
335		epAssertFirstCommitmentUnchanged(t, s, epExpiredAt)
336	
337		// 先占用库存的合格请求只留有首次成功记录；其库存依据是新增占用之前的
338		// 10/0/10，使用两件与后续他人的失败都不改变这条记录。
339		okHistory, err := s.RequestHistory(epQualifiedReq)
340		if err != nil {
341			t.Fatalf("qualified request history: %v", err)
342		}
343		if len(okHistory) != 1 {
344			t.Fatalf("qualified request history length = %d, want 1", len(okHistory))
345		}
346		okRec := okHistory[0]
347		if !okRec.Success || okRec.Error != "" || okRec.CommitID != epFirstCommit ||
348			okRec.Quantity != 8 || !okRec.Expiry.Equal(epCommitExpiry) || !okRec.Now.Equal(epReserveAt) {
349			t.Fatalf("qualified success record altered: %+v", okRec)
350		}
351		if okRec.Eligibility == nil || !okRec.Eligibility.Eligible ||
352			okRec.Eligibility.Excluded || len(okRec.Eligibility.Reasons) != 0 {
353			t.Fatalf("qualified eligibility snapshot altered: %+v", okRec.Eligibility)
354		}
355		if okRec.StockBasis == nil ||
356			*okRec.StockBasis != (StockBasis{PhysicalRemaining: 10, ActiveOccupied: 0, Committable: 10}) {
357			t.Fatalf("qualified stock basis altered: %+v", okRec.StockBasis)
358		}
359	
360		// 已成功编号原样重试：即使本次当前时刻已过保，仍取回首次成功快照
361		// （已用数量为零、未取消），不重新判断资格与库存、不追加历史。
362		snap, err := s.Reserve(epFirstCommit, epQualifiedReq, epPartID, 8, epCommitExpiry, epRetryAt)
363		if err != nil {
364			t.Fatalf("identical retry of succeeded id: %v", err)
365		}
366		if snap.Quantity != 8 || snap.Used != 0 || snap.Canceled || snap.Expired {
367			t.Fatalf("retry snapshot = %+v, want first snapshot (8/used0/not closed)", snap)
368		}
369		okHistory2, err := s.RequestHistory(epQualifiedReq)
370		if err != nil {
371			t.Fatalf("qualified request history after retry: %v", err)
372		}
373		if len(okHistory2) != 1 {
374			t.Fatalf("identical retry appended history: length = %d, want 1", len(okHistory2))
375		}
376		epAssertAccount(t, s, epRetryAt, 8, 6, 2)
377	
378		// 尚未成功预留的被拒编号可按原内容再次提交：仍是资格拒绝（不是缺货），
379		// 再追加一条同样完整的 ineligible 记录，仍不产生承诺、不改动账目。
380		_, err = s.Reserve(epBothCommit, epBothReq, epPartID, 3, epReqExpiry, epExpiredAt)
381		if !errors.Is(err, ErrIneligible) {
382			t.Fatalf("reuse rejected id: got %v, want ErrIneligible", err)
383		}
384		if _, err := s.Commitment(epBothCommit); !errors.Is(err, ErrNotFound) {
385			t.Fatalf("rejected id became a commitment: err=%v", err)
386		}
387		epAssertIneligibleRecord(t, s, epBothReq, epBothCommit, epExpiredAt,
388			[]RejectionReason{ReasonWarrantyExpired, ReasonFaultExcluded}, true, wantBasis, 2)
389		epAssertAccount(t, s, epExpiredAt, 8, 6, 2)
390		epAssertFirstCommitmentUnchanged(t, s, epExpiredAt)
391	}
392	
393	// TestEligibleRequestStillRejectedByStock 对照：产品在保且故障未被除外时，
394	// 库存不足仍按现有规则返回 ErrInsufficientStock；历史保存合格资格依据与
395	// 真实库存依据 8/6/2，类别为 insufficient_stock，不产生承诺。
396	func TestEligibleRequestStillRejectedByStock(t *testing.T) {
397		s := epNewStore(t)
398		if err := s.SubmitRequest(epGoodReq, epProductID, "NOISE"); err != nil {
399			t.Fatalf("submit good request: %v", err)
400		}
401	
402		_, err := s.Reserve(epGoodCommit, epGoodReq, epPartID, 3, epReqExpiry, epWithinAt)
403		if !errors.Is(err, ErrInsufficientStock) {
404			t.Fatalf("reserve eligible but short: got %v, want ErrInsufficientStock", err)
405		}
406		if errors.Is(err, ErrIneligible) {
407			t.Fatalf("stock rejection wrapped ErrIneligible: %v", err)
408		}
409		if _, err := s.Commitment(epGoodCommit); !errors.Is(err, ErrNotFound) {
410			t.Fatalf("stockout rejection created commitment: err=%v", err)
411		}
412	
413		h, err := s.RequestHistory(epGoodReq)
414		if err != nil {
415			t.Fatalf("good request history: %v", err)
416		}
417		if len(h) != 1 {
418			t.Fatalf("good history length = %d, want 1", len(h))
419		}
420		rec := h[0]
421		if rec.Seq != 1 || rec.Success || rec.Error != HistoryErrorInsufficientStock {
422			t.Fatalf("record = seq %d success %v error %q, want 1/false/%q",
423				rec.Seq, rec.Success, rec.Error, HistoryErrorInsufficientStock)
424		}
425		if rec.CommitID != epGoodCommit || rec.PartID != epPartID || rec.Quantity != 3 ||
426			!rec.Expiry.Equal(epReqExpiry) || !rec.Now.Equal(epWithinAt) {
427			t.Fatalf("submission content altered: %+v", rec)
428		}
429		// 合格资格依据与同一时刻直接查询一致：合格、无拒绝原因、未命中除外。
430		direct, err := s.Evaluate(epGoodReq, epWithinAt)
431		if err != nil {
432			t.Fatalf("direct evaluate: %v", err)
433		}
434		if rec.Eligibility == nil {
435			t.Fatal("eligible stockout record missing eligibility basis")
436		}
437		epAssertEligibilityEqual(t, rec.Eligibility, direct, "stockout history vs Evaluate")
438		if !rec.Eligibility.Eligible || rec.Eligibility.Excluded || len(rec.Eligibility.Reasons) != 0 {
439			t.Fatalf("stockout record kept ineligible basis: %+v", rec.Eligibility)
440		}
441		// 库存依据是处理前真实账目 8/6/2，而不是空依据或零值。
442		if rec.StockBasis == nil ||
443			*rec.StockBasis != (StockBasis{PhysicalRemaining: 8, ActiveOccupied: 6, Committable: 2}) {
444			t.Fatalf("stock basis = %+v, want 8/6/2", rec.StockBasis)
445		}
446	
447		epAssertAccount(t, s, epWithinAt, 8, 6, 2)
448		epAssertFirstCommitmentUnchanged(t, s, epWithinAt)
449	}
450	
451	// TestIneligibleBeatsStockWhenCommittableZero 边界：再为合格请求追加两件
452	// 占用，使可承诺恰好为零（实物八件、占用八件）。此时不合格请求（过保加
453	// 除外，以及恰在保修截止时刻的仅过保）仍必须返回 ErrIneligible，历史的
454	// 库存依据是真实的 8/8/0——可承诺为零不能把资格拒绝改报成缺货，实物也
455	// 不能被记成零；在保且未除外的合格请求申请一件则按缺货拒绝，依据同为
456	// 8/8/0 且资格合格。
457	func TestIneligibleBeatsStockWhenCommittableZero(t *testing.T) {
458		s := epNewStore(t)
459	
460		// 再占用剩余可承诺两件：8/6/2 -> 8/8/0。
461		if _, err := s.Reserve(epTailCommit, epQualifiedReq, epPartID, 2, epCommitExpiry, epReserveAt); err != nil {
462			t.Fatalf("reserve tail two units: %v", err)
463		}
464		epAssertAccount(t, s, epWithinAt, 8, 8, 0)
465	
466		wantBasis := StockBasis{PhysicalRemaining: 8, ActiveOccupied: 8, Committable: 0}
467	
468		// 过保且命中除外清单：申请三件，资格拒绝优先于零库存。
469		if err := s.SubmitRequest(epZeroReq, epProductID, "BROKEN_SEAL"); err != nil {
470			t.Fatalf("submit zero-case request: %v", err)
471		}
472		if _, err := s.Reserve(epZeroCommit, epZeroReq, epPartID, 3, epReqExpiry, epExpiredAt); !errors.Is(err, ErrIneligible) {
473			t.Fatalf("reserve ineligible at zero committable: got %v, want ErrIneligible", err)
474		}
475		if _, err := s.Commitment(epZeroCommit); !errors.Is(err, ErrNotFound) {
476			t.Fatalf("zero-committable rejection created commitment: err=%v", err)
477		}
478		epAssertIneligibleRecord(t, s, epZeroReq, epZeroCommit, epExpiredAt,
479			[]RejectionReason{ReasonWarrantyExpired, ReasonFaultExcluded}, true, wantBasis, 1)
480	
481		// 恰在保修截止时刻（仅过保）申请三件：同样是资格拒绝。
482		if err := s.SubmitRequest(epZeroEdgeReq, epProductID, "NOISE"); err != nil {
483			t.Fatalf("submit boundary zero-case request: %v", err)
484		}
485		if _, err := s.Reserve(epZeroEdgeCommit, epZeroEdgeReq, epPartID, 3, epReqExpiry, epDeadline); !errors.Is(err, ErrIneligible) {
486			t.Fatalf("reserve boundary-ineligible at zero committable: got %v, want ErrIneligible", err)
487		}
488		epAssertIneligibleRecord(t, s, epZeroEdgeReq, epZeroEdgeCommit, epDeadline,
489			[]RejectionReason{ReasonWarrantyExpired}, false, wantBasis, 1)
490	
491		// 合格对照：在保且未除外，申请一件也因可承诺为零按缺货拒绝。
492		if err := s.SubmitRequest(epZeroGoodReq, epProductID, "NOISE"); err != nil {
493			t.Fatalf("submit zero-case good request: %v", err)
494		}
495		if _, err := s.Reserve(epZeroGoodCommit, epZeroGoodReq, epPartID, 1, epReqExpiry, epWithinAt); !errors.Is(err, ErrInsufficientStock) {
496			t.Fatalf("reserve eligible at zero committable: got %v, want ErrInsufficientStock", err)
497		}
498		goodHistory, err := s.RequestHistory(epZeroGoodReq)
499		if err != nil {
500			t.Fatalf("zero-case good history: %v", err)
501		}
502		if len(goodHistory) != 1 || goodHistory[0].Error != HistoryErrorInsufficientStock ||
503			goodHistory[0].Eligibility == nil || !goodHistory[0].Eligibility.Eligible {
504			t.Fatalf("zero-case good record altered: %+v", goodHistory)
505		}
506		if goodHistory[0].StockBasis == nil || *goodHistory[0].StockBasis != wantBasis {
507			t.Fatalf("zero-case good stock basis = %+v, want 8/8/0", goodHistory[0].StockBasis)
508		}
509	
510		// 两次资格拒绝与一次缺货拒绝都不产生承诺、不改变账目：仍为 8/8/0，
511		// 明细只有八件（已用两件、未用六件）与两件（未用）两笔有效承诺。
512		epAssertAccount(t, s, epExpiredAt, 8, 8, 0)
513		st, err := s.PartStatus(epPartID, epExpiredAt)
514		if err != nil {
515			t.Fatalf("part status: %v", err)
516		}
517		if len(st.Details) != 2 {
518			t.Fatalf("details = %+v, want only the two successful commitments", st.Details)
519		}
520		first := st.Details[0] // 按承诺编号排序，c-epri-first 在 c-epri-tail 之前
521		tail := st.Details[1]
522		if first.CommitmentID != epFirstCommit || first.OriginalQuantity != 8 ||
523			first.UsedQuantity != 2 || first.RemainingQuantity != 6 || first.Status != CommitmentActive {
524			t.Fatalf("first commitment detail altered under zero committable: %+v", first)
525		}
526		if tail.CommitmentID != epTailCommit || tail.OriginalQuantity != 2 ||
527			tail.UsedQuantity != 0 || tail.RemainingQuantity != 2 || tail.Status != CommitmentActive {
528			t.Fatalf("tail commitment detail altered: %+v", tail)
529		}
530		epAssertFirstCommitmentUnchanged(t, s, epExpiredAt)
531	}
532

